"""Small login function used by the coding-agent demo."""

from config import DEMO_PASSWORD, DEMO_USERNAME


def login(username: str, password: str) -> bool:
    """Accept only the exact example credentials; empty input is rejected."""
    if not isinstance(username, str) or not isinstance(password, str):
        return False
    if not username or not password:
        return False
    return username == DEMO_USERNAME and password == DEMO_PASSWORD

import pytest
from login import login

class AlwaysEqual:
    def __eq__(self, other):
        return True

@pytest.mark.parametrize("username,password", [
    (None, "demo-only"), (42, "demo-only"), ([], "demo-only"),
    (AlwaysEqual(), "demo-only"), ("demo", AlwaysEqual()), ("demo", None),
])
def test_non_string_credentials_are_rejected(username, password):
    assert login(username, password) is False
